//refAssemblies: System.Diagnostics.Process.dll, System.IO.FileSystem.AccessControl.dll, System.Security.AccessControl.dll, System.Security.Principal.Windows.dll
using System;
using System.Diagnostics;
using System.IO;
using System.Security.AccessControl;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Cluster folder: every server of the same owner on this machine shares one folder (the command line passes
// it as -ClusterDirOverride, by default <owner folder>/ArkClusters); the game keeps one sub-folder per
// Cluster ID in it. Both values are read from the command line the server is started with. The Cluster ID
// ends up in a path, so only plain names are accepted.
string commandLine = ThisService.Commandline ?? "";
var idMatch = Regex.Match(commandLine, @"-clusterID=(""[^""]*""|\S*)", RegexOptions.IgnoreCase);
var dirMatch = Regex.Match(commandLine, @"-ClusterDirOverride=(""[^""]*""|\S*)", RegexOptions.IgnoreCase);
if (!idMatch.Success || !dirMatch.Success)
{
    ScriptConsole.WriteLine((object)"The command line has no -clusterID / -ClusterDirOverride; this server is not in a cluster.");
    return;
}
string clusterId = idMatch.Groups[1].Value.Trim('"');
if (!Regex.IsMatch(clusterId, "^[A-Za-z0-9_-]{1,32}$"))
    throw new Exception("Cluster ID \"" + clusterId + "\" is not valid. Use 1-32 letters, numbers, - or _.");

string root = Path.GetFullPath(ThisService.RootDirectory);
string clusterPath = dirMatch.Groups[1].Value.Trim('"');
// Under Wine (Linux node) the game gets the folder as a Z: drive path; Z: is the Linux root.
if (!System.OperatingSystem.IsWindows() && Regex.IsMatch(clusterPath, "^[Zz]:"))
    clusterPath = clusterPath.Substring(2).Replace('\\', '/');
string clusters = Path.GetFullPath(clusterPath);
Directory.CreateDirectory(clusters);

if (System.OperatingSystem.IsWindows())
{
    // The game runs as the service's account, which may not be allowed to write next to the service folder.
    // Give the cluster folder the service folder's allow rules (SYSTEM, Administrators, the service account)
    // and stop it inheriting from the owner folder, so no other account can read or plant cluster data.
    // Rules from every server that joins the cluster add up, so per-service accounts work too.
    var rootAcl = new DirectoryInfo(root).GetAccessControl();
    var clusterInfo = new DirectoryInfo(clusters);
    var clusterAcl = clusterInfo.GetAccessControl();
    clusterAcl.SetAccessRuleProtection(true, false);
    foreach (FileSystemAccessRule rule in rootAcl.GetAccessRules(true, true, typeof(System.Security.Principal.SecurityIdentifier)))
    {
        if (rule.AccessControlType != AccessControlType.Allow)
            continue;
        clusterAcl.AddAccessRule(new FileSystemAccessRule(rule.IdentityReference, rule.FileSystemRights,
            InheritanceFlags.ContainerInherit | InheritanceFlags.ObjectInherit, PropagationFlags.None, AccessControlType.Allow));
    }
    clusterInfo.SetAccessControl(clusterAcl);
}
else
{
    // Linux: the game runs as the service's account; give the cluster folder the owner and mode of the
    // service folder (the per-owner account and no access for other accounts).
    Run("chown", "--reference=\"" + root + "\" \"" + clusters + "\"");
    Run("chmod", "--reference=\"" + root + "\" \"" + clusters + "\"");
}

void Run(string file, string arguments)
{
    using var p = Process.Start(new ProcessStartInfo(file, arguments) { UseShellExecute = false, RedirectStandardError = true });
    string error = p.StandardError.ReadToEnd();
    p.WaitForExit();
    if (p.ExitCode != 0)
        throw new Exception(file + " " + arguments + " failed: " + error.Trim());
}

ScriptConsole.WriteLine((object)("Cluster \"" + clusterId + "\": " + Path.Combine(clusters, clusterId)));

