// browser uses can no longer search sessions from outside the game (Epic answers 403 "missing
// matchmaking:findSessions"). So the server is queried over its own RCON port instead: a successful login
// means it is up, and ListPlayers gives the players. Name, map and cluster come from the command line.
string address = Globals.GetValue<string>("Address");
if (string.IsNullOrEmpty(address)) address = string.IsNullOrEmpty(ThisService.IPAddress) ? "127.0.0.1" : ThisService.IPAddress;
int port = ThisService.RconPort;
string password = ThisService.Variables.Parse<string>("RconPassword", "") ?? "";
string commandLine = ThisService.Commandline ?? "";

