{
    byte[] text = Encoding.UTF8.GetBytes(body);
    byte[] packet = new byte[14 + text.Length];
    BitConverter.GetBytes(10 + text.Length).CopyTo(packet, 0);
    BitConverter.GetBytes(id).CopyTo(packet, 4);
    BitConverter.GetBytes(type).CopyTo(packet, 8);
    text.CopyTo(packet, 12);
    s.Write(packet, 0, packet.Length);
}

(int Id, string Body) Receive(NetworkStream s, int id, bool auth)
{
    while (true)
    {
        byte[] header = new byte[4];
        ReadExactly(s, header, 4);
        int size = BitConverter.ToInt32(header, 0);
        if (size < 10 || size > 1 << 20) throw new IOException("unexpected RCON packet size " + size);
        byte[] data = new byte[size];
        ReadExactly(s, data, size);
        int replyId = BitConverter.ToInt32(data, 0);
        int type = BitConverter.ToInt32(data, 4);
        string body = Encoding.UTF8.GetString(data, 8, size - 10);
        if (auth ? type == 2 : replyId == id) return (replyId, body);
    }
}

// While the server loads or shuts down its RCON port accepts connections but does not answer: report that as
// offline (a normal reading) instead of failing the script.
string playerList = null;
string offlineReason = null;
try
{
    if (password.Length == 0)
        throw new InvalidOperationException("No admin (RCON) password is set");
    using (var client = new TcpClient())
    {
        var connect = client.ConnectAsync(address, port);
        if (await Task.WhenAny(connect, Task.Delay(3000)) != connect)
            throw new InvalidOperationException("RCON port " + port + " is not answering");
        await connect;
        var stream = client.GetStream();
        stream.ReadTimeout = 4000;
        Send(stream, 1, 3, password);
        if (Receive(stream, 1, true).Id == -1)
            throw new InvalidOperationException("the admin (RCON) password was rejected");
        Send(stream, 2, 2, "ListPlayers");
        playerList = Receive(stream, 2, false).Body;
    }
}
catch (Exception ex) when (ex is IOException || ex is SocketException || ex is InvalidOperationException)
{
    offlineReason = ex.Message;
}

if (offlineReason != null)
{
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", offlineReason);
    return;
}

// ListPlayers answers "No Players Connected" or one "<n>. <name>, <EOS id>" line per player.
var players = new List<GameQueryPlayer>();
foreach (Match m in Regex.Matches(playerList, @"^\s*\d+\.\s*(.*?),\s*[0-9a-fA-F]+\s*$", RegexOptions.Multiline))
    players.Add(new GameQueryPlayer { Name = m.Groups[1].Value });

string map = Regex.Match(commandLine, @"^\s*""?([^?\s""]+)").Groups[1].Value;
var nameMatch = Regex.Match(commandLine, @"\?SessionName=(""[^""]*""|[^?\s]*)", RegexOptions.IgnoreCase);
string name = nameMatch.Success ? nameMatch.Groups[1].Value.Trim('"') : ThisService.Name;
string cluster = Regex.Match(commandLine, @"-clusterID=(""[^""]*""|\S*)", RegexOptions.IgnoreCase).Groups[1].Value.Trim('"');

var response = new GameQueryResponse
{
    Status = "UP",
    Hostname = address + ":" + ThisService.GamePort,
    Name = name,
    GameType = "ARK: Survival Ascended",
    Map = map,
    NumPlayers = players.Count,
    MaxPlayers = ThisService.Slots,
    Players = players
};
if (cluster.Length > 0) response.Rules["ClusterID"] = cluster;
Globals.ReturnValue = response;

