using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// The cluster folder is outside the service folder, so the panel's backups can't include it. After every stop
// (a backup stops the server first) save a dated copy of this server's cluster data in
// ShooterGame/Saved/ClusterBackup/<date>/<Cluster ID>, where backups pick it up. The newest 10 copies are kept.
// "Restore cluster data" lists them.
const int KeepCopies = 10;
const string StampFormat = "yyyy-MM-dd_HH-mm-ss";

string commandLine = ThisService.Commandline ?? "";
var idMatch = Regex.Match(commandLine, @"-clusterID=(""[^""]*""|\S*)", RegexOptions.IgnoreCase);
var dirMatch = Regex.Match(commandLine, @"-ClusterDirOverride=(""[^""]*""|\S*)", RegexOptions.IgnoreCase);
if (!idMatch.Success || !dirMatch.Success)
{
    ScriptConsole.WriteLine((object)"The command line has no -clusterID / -ClusterDirOverride; this server is not in a cluster.");
    return;
}
string clusterId = idMatch.Groups[1].Value.Trim('"');
if (!Regex.IsMatch(clusterId, "^[A-Za-z0-9_-]{1,32}$"))
    throw new Exception("Cluster ID \"" + clusterId + "\" is not valid. Use 1-32 letters, numbers, - or _.");

string root = Path.GetFullPath(ThisService.RootDirectory);
string clusterPath = dirMatch.Groups[1].Value.Trim('"');
// Under Wine (Linux node) the game gets the folder as a Z: drive path; Z: is the Linux root.
if (!System.OperatingSystem.IsWindows() && Regex.IsMatch(clusterPath, "^[Zz]:"))
    clusterPath = clusterPath.Substring(2).Replace('\\', '/');
string source = Path.Combine(Path.GetFullPath(clusterPath), clusterId);
string copies = Path.Combine(root, "ShooterGame", "Saved", "ClusterBackup");

if (!Directory.Exists(source))
{
    ScriptConsole.WriteLine((object)("No cluster data yet in " + source + "."));
    return;
}

// Newest copy of this cluster first; folders that aren't dated copies are left alone.
var existing = Directory.Exists(copies)
    ? new DirectoryInfo(copies).EnumerateDirectories()
        .Where(d => Regex.IsMatch(d.Name, @"^\d{4}-\d\d-\d\d_\d\d-\d\d-\d\d$"))
        .OrderByDescending(d => d.Name, StringComparer.Ordinal).ToList()
    : new List<DirectoryInfo>();
var latest = existing.FirstOrDefault(d => Directory.Exists(Path.Combine(d.FullName, clusterId)));
if (latest != null && Fingerprint(Path.Combine(latest.FullName, clusterId)) == Fingerprint(source))
{
    ScriptConsole.WriteLine((object)("Cluster \"" + clusterId + "\" is unchanged since the copy from " + latest.Name + "; no new copy."));
    return;
}

string stamp = DateTime.Now.ToString(StampFormat);
string copy = Path.Combine(copies, stamp);
if (Directory.Exists(copy))
    Directory.Delete(copy, true);
int files = CopyTree(new DirectoryInfo(source), Path.Combine(copy, clusterId));
existing.Insert(0, new DirectoryInfo(copy));
foreach (var old in existing.Where(d => d.Name != stamp).Skip(KeepCopies - 1))
    old.Delete(true);

if (!System.OperatingSystem.IsWindows())
{
    // The script runs as root; hand the copy to the service's account like the rest of the service folder.
    Run("chown", "-R -P --reference=\"" + root + "\" \"" + copies + "\"");
}
ScriptConsole.WriteLine((object)("Cluster \"" + clusterId + "\": saved " + files + " file(s) as ShooterGame/Saved/ClusterBackup/" + stamp + "."));

// Links are skipped, never followed: a link in the cluster folder must not pull outside files into the backup.
int CopyTree(DirectoryInfo from, string to)
{
    Directory.CreateDirectory(to);
    int count = 0;
    var options = new EnumerationOptions { AttributesToSkip = FileAttributes.ReparsePoint };
    foreach (var file in from.EnumerateFiles("*", options))
    {
        file.CopyTo(Path.Combine(to, file.Name), true);
        count++;
    }
    foreach (var dir in from.EnumerateDirectories("*", options))
        count += CopyTree(dir, Path.Combine(to, dir.Name));
    return count;
}

string Fingerprint(string folder)
{
    var options = new EnumerationOptions { AttributesToSkip = FileAttributes.ReparsePoint, RecurseSubdirectories = true };
    using var sha = SHA256.Create();
    var lines = Directory.EnumerateFiles(folder, "*", options)
        .Select(f => Path.GetRelativePath(folder, f).Replace('\\', '/') + "|" + Convert.ToHexString(sha.ComputeHash(File.ReadAllBytes(f))))
        .OrderBy(l => l, StringComparer.Ordinal);
    return string.Join("\n", lines);
}

void Run(string file, string arguments)
{
    using var p = Process.Start(new ProcessStartInfo(file, arguments) { UseShellExecute = false, RedirectStandardError = true });
    string error = p.StandardError.ReadToEnd();
    p.WaitForExit();
    if (p.ExitCode != 0)
        throw new Exception(file + " " + arguments + " failed: " + error.Trim());
}

