if (!Regex.IsMatch(clusterId, "^[A-Za-z0-9_-]{1,32}$"))
    throw new Exception("Cluster ID \"" + clusterId + "\" is not valid. Use 1-32 letters, numbers, - or _.");

string root = Path.GetFullPath(ThisService.RootDirectory);
string clusterPath = dirMatch.Groups[1].Value.Trim('"');
// Under Wine (Linux node) the game gets the folder as a Z: drive path; Z: is the Linux root.
if (!System.OperatingSystem.IsWindows() && Regex.IsMatch(clusterPath, "^[Zz]:"))
    clusterPath = clusterPath.Substring(2).Replace('\\', '/');
string clusters = Path.GetFullPath(clusterPath);
string target = Path.Combine(clusters, clusterId);
string copies = Path.Combine(root, "ShooterGame", "Saved", "ClusterBackup");

// Copies of THIS cluster, newest first. A copy made under another Cluster ID is never offered.
var available = Copies().Where(d => Directory.Exists(Path.Combine(d.FullName, clusterId))).ToList();
if (available.Count == 0)
    throw new Exception("There are no saved copies of cluster \"" + clusterId + "\" in ShooterGame/Saved/ClusterBackup. "
        + "A copy is saved every time the server stops; restore a backup to bring older copies back.");

// <pick>
if (!IsInteractive)
{
    ScriptConsole.WriteLine((object)("Saved copies of cluster \"" + clusterId + "\": " + string.Join(", ", available.Select(d => d.Name))));
    ScriptConsole.WriteLine((object)"Run this from the panel to choose one.");
    return;
}
var combo = new DynamicComboBox
{
    Id = "Copy", Label = "Cluster data to restore", Required = true, DefaultValue = available[0].Name,
    Description = "Saved when the server stopped. The current cluster data is saved as a new copy first."
};
foreach (var d in available)
    combo.Items.Add(new DynamicComboBoxItem { Value = d.Name, Text = Label(d) });
var answer = await ThisScript.Input(new InputConfiguration { IsDialog = true, AllowCancel = true }, combo);
if (answer.Canceled)
{
    ScriptConsole.WriteLine((object)"Cancelled; nothing was changed.");
    return;
}
string chosen = answer.Values?["Copy"]?.ToString() ?? "";
// </pick>

var picked = available.FirstOrDefault(d => d.Name == chosen);
if (picked == null)
    throw new Exception("\"" + chosen + "\" is not one of the saved copies.");
string pickedData = Path.Combine(picked.FullName, clusterId);

// Keep the current data as a copy (unless the newest copy already holds it), never rotating out the one being restored.
if (Directory.Exists(target))
{
    var newest = available[0];
    if (Fingerprint(target) == Fingerprint(Path.Combine(newest.FullName, clusterId)))
        ScriptConsole.WriteLine((object)("The current cluster data is the same as the copy from " + Display(newest.Name) + "."));
    else
    {
        string stamp = DateTime.Now.ToString(StampFormat);
        CopyTree(new DirectoryInfo(target), Path.Combine(copies, stamp, clusterId));
        foreach (var old in Copies().Where(d => d.Name != stamp && d.Name != picked.Name).Skip(KeepCopies - 1))
            old.Delete(true);
        ScriptConsole.WriteLine((object)("The current cluster data was saved as the copy from " + Display(stamp) + "."));
    }
    Directory.Delete(target, true);
}
Directory.CreateDirectory(clusters);
int files = CopyTree(new DirectoryInfo(pickedData), target);

if (!System.OperatingSystem.IsWindows())
{
    // The script runs as root; the game reads and writes the cluster folder as the service's account, and the
    // copies belong to it like the rest of the service folder.
    Run("chown", "-R -P --reference=\"" + clusters + "\" \"" + target + "\"");
    Run("chown", "-R -P --reference=\"" + root + "\" \"" + copies + "\"");
}
ScriptConsole.WriteLine((object)("Cluster \"" + clusterId + "\": restored " + files + " file(s) from the copy from " + Display(picked.Name) + "."));

List<DirectoryInfo> Copies() => Directory.Exists(copies)
    ? new DirectoryInfo(copies).EnumerateDirectories()
        .Where(d => Regex.IsMatch(d.Name, @"^\d{4}-\d\d-\d\d_\d\d-\d\d-\d\d$"))
        .OrderByDescending(d => d.Name, StringComparer.Ordinal).ToList()
    : new List<DirectoryInfo>();

string Display(string stamp) =>
    DateTime.ParseExact(stamp, StampFormat, System.Globalization.CultureInfo.InvariantCulture).ToString("yyyy-MM-dd HH:mm:ss");

string Label(DirectoryInfo copy)
{
    int count = Directory.EnumerateFiles(Path.Combine(copy.FullName, clusterId), "*", SearchOption.AllDirectories).Count();
    return Display(copy.Name) + " (" + count + (count == 1 ? " file)" : " files)");
}

// Links are skipped, never followed.
int CopyTree(DirectoryInfo from, string to)
{
    Directory.CreateDirectory(to);
    int count = 0;
    var options = new EnumerationOptions { AttributesToSkip = FileAttributes.ReparsePoint };
    foreach (var file in from.EnumerateFiles("*", options))
    {
        file.CopyTo(Path.Combine(to, file.Name), true);
        count++;
    }
    foreach (var dir in from.EnumerateDirectories("*", options))
        count += CopyTree(dir, Path.Combine(to, dir.Name));
    return count;
}

string Fingerprint(string folder)
{
    var options = new EnumerationOptions { AttributesToSkip = FileAttributes.ReparsePoint, RecurseSubdirectories = true };
    using var sha = SHA256.Create();
    var lines = Directory.EnumerateFiles(folder, "*", options)
        .Select(f => Path.GetRelativePath(folder, f).Replace('\\', '/') + "|" + Convert.ToHexString(sha.ComputeHash(File.ReadAllBytes(f))))
        .OrderBy(l => l, StringComparer.Ordinal);
    return string.Join("\n", lines);
}

void Run(string file, string arguments)
{
    using var p = Process.Start(new ProcessStartInfo(file, arguments) { UseShellExecute = false, RedirectStandardError = true });
    string error = p.StandardError.ReadToEnd();
    p.WaitForExit();
    if (p.ExitCode != 0)
        throw new Exception(file + " " + arguments + " failed: " + error.Trim());
}
